-- Lot 205 : payloads 121 a 150 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_extension_payloads;
create temporary table lot_extension_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-371","moteur":"chatgpt","payload":"[RaccourcIA — /passporteras]\n\nMISSION\nRecréez la même personne photographiée par quatre technologies ou époques différentes. Produire quatre portraits frontaux du même âge avec procédés, coiffures, tenues et colorimétries cohérents.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelles époques souhaitez-vous comparer ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 1 question sur toute l’exécution.\n\nEXÉCUTION\nProduire quatre portraits frontaux du même âge avec procédés, coiffures, tenues et colorimétries cohérents. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nIdentité, âge, carnation, regard et cadrage constant.\n\nÉVITER ET RESPONSABILITÉ\nDocument officiel falsifié, numéro ou sceau inventé, vieillissement non demandé, texte administratif et anachronisme. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"742f30e3fd4a73064e8c401b8e43181c26c8575fae984e9ab79d0dcd9f68f340"},{"ref":"RCI-IMG-371","moteur":"claude","payload":"[RaccourcIA — /passporteras]\n\nMISSION\nRecréez la même personne photographiée par quatre technologies ou époques différentes. Produire quatre portraits frontaux du même âge avec procédés, coiffures, tenues et colorimétries cohérents.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, consolide-les sans longue reformulation et vérifie les capacités réellement disponibles avant de produire. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelles époques souhaitez-vous comparer ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 1 question sur toute l’exécution.\n\nEXÉCUTION\nProduire quatre portraits frontaux du même âge avec procédés, coiffures, tenues et colorimétries cohérents. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nIdentité, âge, carnation, regard et cadrage constant.\n\nÉVITER ET RESPONSABILITÉ\nDocument officiel falsifié, numéro ou sceau inventé, vieillissement non demandé, texte administratif et anachronisme. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"323c0163314bd3f45fd82957b948cae70dcf3e7341e3ca6636ee781e59d4db05"},{"ref":"RCI-IMG-371","moteur":"gemini","payload":"[RaccourcIA — /passporteras]\n\nMISSION\nRecréez la même personne photographiée par quatre technologies ou époques différentes. Produire quatre portraits frontaux du même âge avec procédés, coiffures, tenues et colorimétries cohérents.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte et relie chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelles époques souhaitez-vous comparer ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 1 question sur toute l’exécution.\n\nEXÉCUTION\nProduire quatre portraits frontaux du même âge avec procédés, coiffures, tenues et colorimétries cohérents. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nIdentité, âge, carnation, regard et cadrage constant.\n\nÉVITER ET RESPONSABILITÉ\nDocument officiel falsifié, numéro ou sceau inventé, vieillissement non demandé, texte administratif et anachronisme. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"35af05c91a975fedcdc14ff900dd8648871053598ccd9022cb72ad1e02bd065c"},{"ref":"RCI-IMG-372","moteur":"chatgpt","payload":"[RaccourcIA — /tradingcard]\n\nMISSION\nTransformez une personne, un animal ou un objet en carte de collection originale. Créer une carte originale lisible avec portrait central, hiérarchie, attributs fournis et cadre non affilié à une franchise.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quels nom, capacités ou statistiques exacts doivent apparaître ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 1 question sur toute l’exécution.\n\nEXÉCUTION\nCréer une carte originale lisible avec portrait central, hiérarchie, attributs fournis et cadre non affilié à une franchise. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 4:5; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nIdentité du sujet, texte exact, cohérence des chiffres et lisibilité mobile.\n\nÉVITER ET RESPONSABILITÉ\nFranchise copiée, statistiques inventées si elles sont présentées comme réelles, texte illisible et faux logo. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 4:5, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"eed705f00b0e6200d2c1525a42a77452c2e4dcd27e8aa3a5c428dcc8890a7ef2"},{"ref":"RCI-IMG-372","moteur":"claude","payload":"[RaccourcIA — /tradingcard]\n\nMISSION\nTransformez une personne, un animal ou un objet en carte de collection originale. Créer une carte originale lisible avec portrait central, hiérarchie, attributs fournis et cadre non affilié à une franchise.\n\nDÉCISION\nRepère d’abord les contrain